#====================================================================================
#
# Dataset: Puntenwolk
# Doel: De publicatie van deze puntenwolk-data dient om de efficiëntie in de bouw en civiele techniek te verhogen door een nauwkeurige digitale basis te bieden voor ontwerp en uitvoering. Daarnaast ondersteunt de data geavanceerd asset management van de openbare ruimte en levert het cruciale inzichten voor vraagstukken rondom klimaat en veiligheid. Door deze informatie breed toegankelijk te maken, faciliteren we een slimmere en snellere inrichting van onze leefomgeving.
#
#====================================================================================
MAP
  NAME                      "puntenwolk"
  INCLUDE                   "header.inc"

  WEB
    METADATA
      "team"                "DPGEO"        
      "ows_title"           "Puntenwolk Gemeente Amsterdam"
      "ows_abstract"        "puntenwolk"
      "ows_onlineresource"  "MAP_URL_REPLACE/maps/puntenwolk"
    END
  END

  #-----------------------------------------------------------------------------
  # Layers
  #-----------------------------------------------------------------------------    
  ## Puntenwolk 2026  
  LAYER
    NAME                    "puntenwolk_2026"
    GROUP                   "puntenwolk" 
    PROJECTION
      "init=epsg:28992"
    END
    INCLUDE                 "connection/dataservices.inc"
    DATA                    "geometrie from public.puntenwolk_metadata_2026_v1 USING srid=28992 USING UNIQUE id"
    TYPE                    POLYGON
    TEMPLATE "fooOnlyForWMSGetFeatureInfo.html"
    MINSCALEDENOM           10
    MAXSCALEDENOM           72224 


    METADATA
      "gml_include_items"   "all"
      "wms_title"           "Puntenwolk 2026"
      "wms_enable_request"  "*"
      "wms_group_title"     "Puntenwolk"
      "wms_abstract"        "Puntenwolk dataset 2026"
      "wms_srs"             "EPSG:28992"
      "wms_name"            "Metadata 2026"
      "wms_server_version"  "1.3.0"
      "wms_extent"          "100000 450000 150000 500000"
      "gml_featureid"       "id"
      "gml_geometries"      "geometrie"
      "gml_geometry_type"   "polygon"
      "gml_include_items"   "all"
      "gml_types"           "auto"
      "wms_include_items"   "all"      
    END

    CLASS
      NAME          "Puntenwolk 2026"

      STYLE
          ANTIALIAS    true
          COLOR        248 153 0
          OPACITY      30
      END
      STYLE
          OUTLINECOLOR        35 35 35
          OPACITY      100
          WIDTH        0.5
      END
    END
  END
# Puntenwolk 2025  
  LAYER
    NAME                    "puntenwolk_2025"
    GROUP                   "puntenwolk" 
    PROJECTION
      "init=epsg:28992"
    END
    INCLUDE                 "connection/dataservices.inc"
    DATA                    "geometrie from public.puntenwolk_metadata_2025_v1 USING srid=28992 USING UNIQUE id"
    TYPE                    POLYGON
    TEMPLATE "fooOnlyForWMSGetFeatureInfo.html"
    MINSCALEDENOM           10
    MAXSCALEDENOM           72224 


    METADATA
      "gml_include_items"   "all"
      "wms_title"           "Puntenwolk 2025"
      "wms_enable_request"  "*"
      "wms_group_title"     "Puntenwolk"
      "wms_abstract"        "Puntenwolk dataset 2025"
      "wms_srs"             "EPSG:28992"
      "wms_name"            "Puntenwolk 2025"
      "wms_server_version"  "1.3.0"
      "wms_extent"          "100000 450000 150000 500000"
      "gml_featureid"       "id"
      "gml_geometries"      "geometrie"
      "gml_geometry_type"   "polygon"
      "gml_include_items"   "all"
      "gml_types"           "auto"
      "wms_include_items"   "all"      
    END

    CLASS
      NAME          "Puntenwolk 2025"

      STYLE
          ANTIALIAS    true
          COLOR 0 119 22
          OPACITY      20
      END
      STYLE
          OUTLINECOLOR        0 119 22
          OPACITY      100
          WIDTH        0.5
      END
    END
  END
END
